<section class="panel table-panel" data-module-table>
  <div class="panel-head"><div class="panel-title"><h3><?= e($module['title']) ?></h3><p><?= e($module['subtitle']) ?></p></div><span class="badge <?= $databaseConnected || $module['key'] === 'mediciones' ? 'ok' : 'warn' ?>"><?= count($rows) ?> registros reales</span></div>
  <div class="table-tools"><label class="field has-icon"><input type="search" data-table-search placeholder="Buscar en <?= e(strtolower($module['title'])) ?>..."></label><label class="field"><select data-table-status><option value="">Todos los estados</option><option value="activo">Activo</option><option value="inactivo">Inactivo</option><option value="conectado">Conectado</option><option value="desconectado">Desconectado</option></select></label></div>
  <?php if (!$databaseConnected && $module['key'] !== 'mediciones'): ?><div class="alert error">Configure MySQL en <a class="text-link" href="<?= url('configuracion') ?>">Configuración</a> para consultar este módulo. No se muestran datos de ejemplo.</div><?php endif; ?>
  <div class="table-scroll"><table><thead><tr><?php foreach (array_keys($rows[0] ?? []) as $column): ?><th><?= e($column) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><?php foreach ($row as $key => $value): ?><td><?= $key === 'Estado' ? '<span class="badge ' . (in_array(strtolower((string)$value), ['activo','conectado','procesado','válido'], true) ? 'ok' : 'warn') . '">' . e($value) . '</span>' : e($value) ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table><?php if (!$rows): ?><div class="empty">No existen registros en este módulo.</div><?php endif; ?></div>
  <div class="table-footer"><span data-table-count>Mostrando <?= count($rows) ?> registros</span></div>
</section>
